  KEY `t_value` (`t_value`),
  KEY `data_template_id` (`data_template_id`),
  KEY `local_data_id` (`local_data_id`),
  KEY `host_id` (`host_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
