CREATE TABLE `graph_templates` (
  `id` mediumint unsigned NOT NULL AUTO_INCREMENT,
  `hash` char(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `name` char(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
