  PRIMARY KEY (`id`),
  KEY `multiple_name` (`multiple`,`name`),
  KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=331 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Contains each graph template name.';
