--
-- Table structure for table `graph_templates_item`
--

DROP TABLE IF EXISTS `graph_templates_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `graph_templates_item` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `hash` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `local_graph_template_item_id` int unsigned NOT NULL DEFAULT '0',
  `local_graph_id` int unsigned NOT NULL DEFAULT '0',
  `graph_template_id` mediumint unsigned NOT NULL DEFAULT '0',
  `task_item_id` int unsigned NOT NULL DEFAULT '0',
  `color_id` mediumint unsigned NOT NULL DEFAULT '0',
  `alpha` char(2) COLLATE utf8mb4_unicode_ci DEFAULT 'FF',
  `color2_id` mediumint unsigned DEFAULT '0',
  `alpha2` char(2) COLLATE utf8mb4_unicode_ci DEFAULT 'FF',
  `gradheight` tinyint DEFAULT '50',
  `graph_type_id` tinyint unsigned NOT NULL DEFAULT '0',
  `line_width` decimal(4,2) DEFAULT '0.00',
  `dashes` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dash_offset` mediumint DEFAULT NULL,
  `cdef_id` mediumint unsigned NOT NULL DEFAULT '0',
  `vdef_id` mediumint unsigned NOT NULL DEFAULT '0',
  `shift` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `consolidation_function_id` tinyint unsigned NOT NULL DEFAULT '0',
  `textalign` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `text_format` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `legend` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `value` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hard_return` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gprint_id` mediumint unsigned NOT NULL DEFAULT '0',
  `sequence` mediumint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `graph_template_id` (`graph_template_id`),
  KEY `local_graph_id_sequence` (`local_graph_id`,`sequence`),
  KEY `local_graph_template_item_id` (`local_graph_template_item_id`),
  KEY `task_item_id` (`task_item_id`),
  KEY `cdef_id` (`cdef_id`),
  KEY `vdef_id` (`vdef_id`),
  KEY `color_id` (`color_id`),
  KEY `gprint_id` (`gprint_id`),
  KEY `lgi_gti` (`local_graph_id`,`graph_template_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9839 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Stores the actual graph item data.';
